import {INSTRUMENTS,copy,uid,noteName} from './music.js';
import {capturePattern,linkClip,detachPatternClip,updatePattern,removePattern,patternInstances} from './patterns.js';
import {createPatternTransferUI} from './pattern-transfer-ui.js';
import {createPatternArrangeUI} from './pattern-arrange-ui.js';
import {createPatternTransformUI} from './pattern-transform-ui.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),round=n=>+n.toFixed(4);
// The library is deliberately the only shared editor. Piano/drum edits remain local.
export function createPatternUI({getProject,getRevision,getSelection,commit,protectedChange,modal,toast,clipSVG,download,projectFilename,locate}){
 const transfer=createPatternTransferUI({getProject,getRevision,commit,modal,toast,download,projectFilename,clipSVG,library});
 const arrange=createPatternArrangeUI({getProject,getRevision,getSelection,commit,protectedChange,modal,toast,library,locate});
 const transform=createPatternTransformUI({getProject,getRevision,commit,protectedChange,modal,toast,clipSVG,library});
 const guard=at=>{if(at!==getRevision())throw Error('工程已改变，请关闭后重新打开 Pattern 窗口。')};
 const error=e=>{const node=$('#pattern-error');if(node)node.textContent=e.message;else toast(e.message)};
 const refsHTML=refs=>refs.length?`<div class="pattern-refs">${refs.slice(0,32).map(r=>`<span>${escape(r.trackName)} · 第 ${+(r.start/4+1).toFixed(3)} 小节${r.muted?' · 块静音':''}</span>`).join('')}${refs.length>32?`<span>另有 ${refs.length-32} 个关联音块</span>`:''}</div>`:'<p class="review-caption">尚无关联音块；它已经存入工程，随时可以放置。</p>';
 const selected=()=>{const {trackId,clipId}=getSelection(),track=getProject().tracks.find(t=>t.id===trackId),clip=track?.clips.find(c=>c.id===clipId);if(!clip)throw Error('请先选一个音块');return{track,clip}};
 function library(patternId){
  transfer.invalidate();arrange.invalidate();
  const p=getProject(),at=getRevision(),list=p.patterns||[],source=list.find(x=>x.id===patternId)||list[0],refs=source?patternInstances(p,source.id):[];
  modal('Pattern 库 · 共享乐句',`<div class="pattern-library"><p>一个源乐句可以关联到多个音块。<strong>只有明确的“共享编辑 / 共享变换”会同步全部关联块。</strong>钢琴卷帘、鼓步进与局部编曲会让改动的块自动独立，不影响其他引用。</p><div class="transfer-tools"><button class="quiet" id="pattern-import-file">导入乐句文件</button><button class="quiet" id="pattern-export-file" ${list.length?'':'disabled'}>导出库中乐句</button><span>跨工程收藏 · 不播放</span></div><div class="pattern-library-layout"><nav class="pattern-list" aria-label="工程中的 Pattern">${list.map(x=>`<button class="quiet ${x===source?'active':''}" data-pattern="${escape(x.id)}" aria-pressed="${x===source}"><strong>${escape(x.name)}</strong><small>${x.length/4} 小节 · ${x.notes.length} 音符 · ${patternInstances(p,x.id).length} 关联</small></button>`).join('')||'<p>库里还是空的。从当前音块存入你的第一个乐句。</p>'}</nav><section class="pattern-detail">${source?`<span class="eyebrow">${escape(INSTRUMENTS[source.instrument].label)} · 固定 MIDI 音高</span><h3>${escape(source.name)}</h3><div class="chord-note-map" style="--track-color:#b7d889">${clipSVG({notes:source.notes},0,source.length)}</div><div class="pattern-actions"><button class="accent" id="pattern-place">放置到轨道</button><button class="quiet" id="pattern-shared">共享编辑 · ${refs.length} 块</button><button class="quiet" id="pattern-transform">共享变换 · ${refs.length} 块</button><button class="quiet" id="pattern-link">关联当前音块</button><button class="quiet" id="pattern-export-one">导出此乐句</button><button class="quiet danger" id="pattern-delete">删除源乐句</button></div><h4>关联音块 · ${refs.length} 个</h4><button class="quiet" id="pattern-manage">选择管理关联块</button>${refsHTML(refs)}`:'<span class="eyebrow">把喜欢的乐句留住</span><h3>保存一次，多处编排。</h3><p>可以放成共享引用，也可以放成独立副本。普通复制和连续复制仍然是独立副本。</p>'}</section></div><div class="modal-notice">旋律可放到任意旋律乐器轨；鼓仅限同种鼓轨。不会自动按调性移调。库与引用保存在 .sprout 工程内，MIDI / WAV 导出实际实例，不额外导出库中未放置的源乐句。</div><div id="pattern-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" data-close>关闭</button><button class="accent" id="pattern-capture">从当前音块存入</button>');
  document.querySelectorAll('[data-pattern]').forEach(b=>b.onclick=()=>{try{guard(at);library(b.dataset.pattern)}catch(e){error(e)}});
  $('#pattern-capture').onclick=()=>{try{guard(at);capture()}catch(e){error(e)}};
  $('#pattern-import-file').onclick=()=>{try{guard(at);transfer.importFile()}catch(e){error(e)}};
  $('#pattern-export-file').onclick=()=>{try{guard(at);transfer.exportFile()}catch(e){error(e)}};
  if(!source)return;
  $('#pattern-export-one').onclick=()=>{try{guard(at);transfer.exportFile(source.id)}catch(e){error(e)}};
  $('#pattern-manage').onclick=()=>{try{guard(at);arrange.manage(source.id)}catch(e){error(e)}};
  $('#pattern-place').onclick=()=>{try{guard(at);place(source.id)}catch(e){error(e)}};
  $('#pattern-shared').onclick=()=>{try{guard(at);shared(source.id)}catch(e){error(e)}};
  $('#pattern-transform').onclick=()=>{try{guard(at);transform(source.id)}catch(e){error(e)}};
  $('#pattern-link').onclick=()=>{try{guard(at);link(source.id)}catch(e){error(e)}};
  $('#pattern-delete').onclick=()=>{try{guard(at);remove(source.id)}catch(e){error(e)}};
 }
 function capture(){
  const {track,clip}=selected(),at=getRevision();
  modal('存入 Pattern 库',`<div class="pattern-form"><p>来源：${escape(track.name)} · ${escape(clip.name)}。保存音符、力度与微偏移，不改变轨道混音。</p><label class="modal-label" for="pattern-name">乐句名称</label><input id="pattern-name" maxlength="60" value="${escape(clip.name)}"><label class="check-label"><input id="pattern-link-source" type="checkbox">同时把当前音块关联到这个源乐句</label><div class="modal-notice">不勾选：只存入库，当前音块保持独立。勾选：当前音块也会接收将来的共享编辑；当前音符听感不变。可撤销。</div><div id="pattern-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="pattern-save">存入工程</button>');
  $('#pattern-save').onclick=()=>{try{guard(at);const result=capturePattern(getProject(),track.id,clip.id,{name:$('#pattern-name').value.trim()||clip.name,linkSource:$('#pattern-link-source').checked});if(commit(result.project)){toast('乐句已存入工程的 Pattern 库。');library(result.patternId)}}catch(e){error(e)}};
 }
 function detach(){try{const {track,clip}=selected();if(!clip.patternId)return toast('这个音块已经是独立副本。');if(commit(detachPatternClip(getProject(),track.id,clip.id)))toast('此音块已独立化。现有音符不变，以后共享编辑不会影响它。')}catch(e){toast(e.message)}}
 function place(id){arrange.place(id)}
 function link(id){
  const {track,clip}=selected(),at=getRevision(),source=getProject().patterns.find(x=>x.id===id);
  modal('关联当前音块',`<div class="pattern-form"><p>把 ${escape(track.name)} · ${escape(clip.name)} 关联到 <strong>${escape(source.name)}</strong>。</p><label class="check-label"><input id="pattern-replace" type="checkbox">明确替换此块内容，再关联（会先备份）</label><div class="modal-notice">默认只接受音符相同、长度相等的音块。勾选替换会用源乐句替换这个块的音符，仍要求长度相等。其他块与轨道混音保持。</div><div id="pattern-preview" class="chord-preview"></div><div id="pattern-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" id="pattern-back">返回库</button><button class="accent" id="pattern-apply">备份并关联</button>');
  const plan=()=>{guard(at);return linkClip(getProject(),id,track.id,clip.id,{replace:$('#pattern-replace').checked})};
  const update=()=>{try{plan();$('#pattern-preview').textContent=$('#pattern-replace').checked?'将替换此块音符，其他关联块不改变。':'音符与源乐句相同，只建立共享关联。';$('#pattern-error').textContent='';$('#pattern-apply').disabled=false}catch(e){error(e);$('#pattern-preview').textContent='尚未关联，没有改变工程。';$('#pattern-apply').disabled=true}};
  $('#pattern-replace').onchange=update;$('#pattern-back').onclick=()=>library(id);$('#pattern-apply').onclick=async()=>{try{const next=plan();$('#modal').close();await protectedChange(()=>{if(commit(next))toast('当前音块已关联，可撤销。')},'关联 Pattern 前 · '+source.name)}catch(e){error(e)}};update();
 }
 function remove(id){
  const p=getProject(),source=p.patterns.find(x=>x.id===id),at=getRevision(),refs=patternInstances(p,id);
  modal('删除库中的源乐句？',`<div class="pattern-form"><p>${escape(source.name)}</p><div class="modal-notice">${refs.length?`仍有 ${refs.length} 个关联音块。删除后它们全部独立化，现有音符、位置、静音与混音均保留，不会从歌曲里消失。`:'没有关联音块，仅删除库中的源乐句。'}<br>先保存备份，整项操作可以撤销。</div>${refsHTML(refs)}<div id="pattern-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" id="pattern-back">取消，返回库</button><button class="danger" id="pattern-apply">保留音符并删除源乐句</button>');
  $('#pattern-back').onclick=()=>library(id);$('#pattern-apply').onclick=async()=>{try{guard(at);const next=removePattern(getProject(),id,{detach:true});$('#modal').close();await protectedChange(()=>{if(commit(next)){toast('源乐句已删除，已有音块的音符保留。');library()}},'删除 Pattern 前 · '+source.name)}catch(e){error(e)}};
 }
 function shared(id){
  const p=getProject(),source=p.patterns.find(x=>x.id===id),at=getRevision(),refs=patternInstances(p,id),draft=copy(source);let page=0;
  modal('共享编辑 · 会同步关联音块',`<div class="pattern-form pattern-shared"><p>正在改库中的源乐句，不是单个音块。应用时将同步 <strong>${refs.length} 个关联音块</strong>；已有独立副本不会改变。此窗口不播放声音。</p><div class="chord-fields"><label>源乐句名称<input id="pattern-name" maxlength="60" value="${escape(draft.name)}"></label><label>长度（拍）<input id="pattern-length" type="number" min="0.25" max="256" step="0.25" value="${draft.length}"></label></div><div class="pattern-actions"><button class="quiet compact" id="pattern-add-note">＋ 音符</button><button class="quiet compact" id="pattern-crop">按新长度裁掉尾部</button><button class="quiet compact" id="pattern-up" ${source.kind==='drum'?'disabled':''}>整体升半音</button><button class="quiet compact" id="pattern-down" ${source.kind==='drum'?'disabled':''}>整体降半音</button><label class="pattern-bulk">统一力度<input id="pattern-velocity" type="number" min="1" max="127" value="80" aria-label="源乐句统一力度"><button class="quiet compact" id="pattern-set-velocity">设定</button></label></div><div id="pattern-notes" class="pattern-note-table"></div><div class="pattern-pagination"><button class="quiet compact" id="pattern-prev">上一页</button><span id="pattern-page"></span><button class="quiet compact" id="pattern-next">下一页</button></div><div id="pattern-preview" class="chord-preview" aria-live="polite"></div><details class="chord-advanced"><summary>查看将同步的 ${refs.length} 个音块</summary>${refsHTML(refs)}</details><div class="modal-notice">位置以源乐句开头的 0 拍计算。长度缩短不会偷偷丢音符：先明确“裁掉尾部”。加长遇到相邻音块或超出工程，会整项拒绝。应用前备份；全部同步作为一次编辑，可撤销。</div><div id="pattern-error" role="status" class="export-progress"></div></div>`,'<button class="quiet" id="pattern-back">取消，返回库</button><button class="accent" id="pattern-apply">备份并同步全部关联块</button>');
  const plan=()=>{guard(at);return updatePattern(getProject(),id,{name:$('#pattern-name').value.trim()||source.name,length:+$('#pattern-length').value,notes:draft.notes})};
  const update=()=>{try{const result=plan(),changed=JSON.stringify(result.project.patterns.find(x=>x.id===id))!==JSON.stringify(source);$('#pattern-preview').innerHTML=`<span class="eyebrow">静音音符预览</span><h3>${result.project.patterns.find(x=>x.id===id).notes.length} 音符 · ${result.affected.length} 个关联块将同步</h3><div class="chord-note-map" style="--track-color:#b7d889">${clipSVG({notes:draft.notes},0,+$('#pattern-length').value)}</div><small>${changed?'应用前未修改工程。独立音块与轨道混音保持。':'还没有修改，可直接返回库。'}</small>`;$('#pattern-error').textContent='';$('#pattern-apply').disabled=!changed}catch(e){error(e);$('#pattern-preview').textContent='修改未应用，请调整音符或长度。';$('#pattern-apply').disabled=true}};
  function rows(){
   page=Math.max(0,Math.min(page,Math.ceil(draft.notes.length/24)-1));const start=page*24;
   $('#pattern-notes').innerHTML=`<div class="pattern-note-head"><span>音高</span><span>位置 / 拍</span><span>长度 / 拍</span><span>力度</span><span>微偏移 / 拍</span><span></span></div>${draft.notes.slice(start,start+24).map((n,i)=>`<div class="pattern-note-row" data-index="${start+i}"><label><span>${noteName(n.pitch)}</span><input data-field="pitch" type="number" min="24" max="108" step="1" value="${n.pitch}" aria-label="源音符 ${start+i+1} 音高" ${source.kind==='drum'?'disabled':''}></label><input data-field="start" type="number" min="0" max="256" step="0.25" value="${n.start}" aria-label="源音符 ${start+i+1} 位置"><input data-field="duration" type="number" min="0.03125" max="256" step="0.25" value="${n.duration}" aria-label="源音符 ${start+i+1} 长度"><input data-field="velocity" type="number" min="1" max="127" step="1" value="${n.velocity}" aria-label="源音符 ${start+i+1} 力度"><input data-field="timingOffset" type="number" min="-0.04" max="0.04" step="0.001" value="${n.timingOffset||0}" aria-label="源音符 ${start+i+1} 微偏移"><button class="quiet" data-remove="${start+i}" aria-label="删除源音符 ${start+i+1}">×</button></div>`).join('')||'<p class="review-caption">还没有音符。可以添加，或从其他音块存入新的乐句。</p>'}`;
   $('#pattern-page').textContent=`${page+1} / ${Math.max(1,Math.ceil(draft.notes.length/24))} 页 · ${draft.notes.length} 音符`;$('#pattern-prev').disabled=page===0;$('#pattern-next').disabled=(page+1)*24>=draft.notes.length;
  }
  $('#pattern-notes').oninput=e=>{const field=e.target.dataset.field,row=e.target.closest('[data-index]');if(!field||!row)return;draft.notes[+row.dataset.index][field]=+e.target.value;if(field==='pitch')row.querySelector('label>span').textContent=Number.isFinite(+e.target.value)?noteName(+e.target.value):'?';update()};
  $('#pattern-notes').onclick=e=>{const b=e.target.closest('[data-remove]');if(!b)return;draft.notes.splice(+b.dataset.remove,1);rows();update()};
  $('#pattern-prev').onclick=()=>{page--;rows()};$('#pattern-next').onclick=()=>{page++;rows()};
  $('#pattern-add-note').onclick=()=>{draft.notes.push({id:uid(),pitch:source.kind==='drum'?INSTRUMENTS[source.instrument].pitch:60,start:0,duration:Math.min(.25,+$('#pattern-length').value||.25),velocity:80});page=Math.floor((draft.notes.length-1)/24);rows();update()};
  $('#pattern-crop').onclick=()=>{const end=+$('#pattern-length').value;if(!Number.isFinite(end)||end<.25||end>256)return error(Error('长度须为 0.25–256 拍'));draft.notes=draft.notes.filter(n=>n.start<end&&end-n.start>=.03125).map(n=>{const duration=round(Math.min(n.duration,end-n.start)),low=-Math.min(.04,n.start),high=Math.min(.04,end-n.start-duration);return{...n,duration,timingOffset:round(Math.max(low,Math.min(high,n.timingOffset||0)))}});rows();update()};
  const transpose=delta=>{if(draft.notes.some(n=>n.pitch+delta<24||n.pitch+delta>108))return error(Error('整体移调超出 24–108 音高范围，没有移动任何音符'));draft.notes.forEach(n=>n.pitch+=delta);rows();update()};
  $('#pattern-up').onclick=()=>transpose(1);$('#pattern-down').onclick=()=>transpose(-1);$('#pattern-set-velocity').onclick=()=>{const value=+$('#pattern-velocity').value;if(!Number.isInteger(value)||value<1||value>127)return error(Error('力度须为 1–127 整数'));draft.notes.forEach(n=>n.velocity=value);rows();update()};
  $('#pattern-name').oninput=update;$('#pattern-length').oninput=update;$('#pattern-back').onclick=()=>library(id);
  $('#pattern-apply').onclick=async()=>{try{const result=plan();$('#modal').close();await protectedChange(()=>{if(commit(result.project)){toast(`已同步 ${result.affected.length} 个关联音块，可一起撤销。`);library(id)}},'共享 Pattern 编辑前 · '+source.name)}catch(e){error(e)}};rows();update();
 }
 return{library,capture,detach,shared,transform};
}
